				"--dsw-font-xxxs-11-line-height": "13px",
				"--dsw-font-xxxs-11-font-size": "10px",
				"--dsw-font-xxxs-11-font-style": "normal",
				"--dsw-font-xxxs-strong-11": "500 10px/13px var(--dsw-font-family)",
				"--dsw-font-xxxs-strong-11-font-family": "var(--dsw-font-family)",
				"--dsw-font-xxxs-strong-11-font-weight": "500",
				"--dsw-font-xxxs-strong-11-line-height": "13px",
				"--dsw-font-xxxs-strong-11-font-size": "10px",
